<section class="correction-hero"><div><span class="eyebrow">Administração</span><h2>Correções administrativas</h2><p>Localize amostras, corrija informações registradas e consulte o histórico de alterações.</p></div></section>
<section class="correction-metrics"><article><strong><?= $metrics['located'] ?></strong><span>Amostras localizadas</span></article><article><strong><?= $metrics['corrections'] ?></strong><span>Correções no período</span></article><article><strong><?= $metrics['cancellations'] ?></strong><span>Cancelamentos</span></article><article><strong><?= $metrics['results'] ?></strong><span>Resultados retificados</span></article></section>
<form class="content-card correction-filters" method="get"><label>Nº da doação<input name="donation" value="<?= $h($filters['donation']) ?>"></label><label>Código LCQH<input name="lcqh" value="<?= $h($filters['lcqh']) ?>"></label><label>Hemocomponente<select name="component"><option value="">Todos</option><?php foreach($components as$c):?><option value="<?= (int)$c['id'] ?>" <?= $filters['component']==$c['id']?'selected':'' ?>><?= $h($c['name']) ?></option><?php endforeach?></select></label><label>Origem / unidade<select name="origin"><option value="">Todas</option><?php foreach($units as$u):?><option value="<?= (int)$u['id'] ?>" <?= $filters['origin']==$u['id']?'selected':'' ?>><?= $h($u['name']) ?></option><?php endforeach?></select></label><label>Finalidade<select name="purpose"><option value="">Todas</option><?php foreach($purposeOptions as$v=>$l):?><option value="<?= $h($v) ?>" <?= $filters['purpose']===$v?'selected':'' ?>><?= $h($l) ?></option><?php endforeach?></select></label><label>Status<select name="status"><option value="">Todos</option><?php foreach(['registered','sent','awaiting_receipt','received','rejected','in_analysis','partial_results','completed','cancelled']as$v):?><option value="<?= $v ?>" <?= $filters['status']===$v?'selected':'' ?>><?= $h(ucfirst(str_replace('_',' ',$v))) ?></option><?php endforeach?></select></label><label>Recebimento de<input type="date" name="received_from" value="<?= $h($filters['received_from']) ?>"></label><label>até<input type="date" name="received_to" value="<?= $h($filters['received_to']) ?>"></label><label>Possui correção<select name="corrected"><option value="">Todos</option><option value="yes" <?= $filters['corrected']==='yes'?'selected':'' ?>>Sim</option><option value="no" <?= $filters['corrected']==='no'?'selected':'' ?>>Não</option></select></label><div class="filter-actions"><button class="button" type="submit">Filtrar</button><a class="button button-light" href="/admin/corrections">Limpar filtros</a></div></form>
<section class="content-card correction-table-card"><div class="table-wrap"><table class="correction-table"><thead><tr><th>Nº da doação</th><th>Código LCQH</th><th>Hemocomponente</th><th>Origem</th><th>Finalidade</th><th>Recebimento</th><th>Status</th><th>Resultados</th><th>Ações</th></tr></thead><tbody><?php foreach($samples as$s):?><tr><td><strong><?= $h($s['donation_number']?:'—') ?></strong><?php if($s['corrected']):?><span class="correction-badge">CORRIGIDA</span><?php endif?></td><td><?= $h($s['lcqh_code']?:'—') ?></td><td><?= $h($s['component_name']?:'—') ?></td><td><?= $h($s['origin_name']?:'—') ?></td><td><?= $h($s['purpose_label']) ?></td><td><?= $s['received_at']?date('d/m/Y H:i',strtotime($s['received_at'])):'—' ?></td><td><span class="status-pill status-<?= $h($s['status']) ?>"><?= $h($s['status_label']) ?></span></td><td><?= (int)$s['result_count'] ?></td><td><a class="button button-small" href="/admin/corrections/view?id=<?= (int)$s['id'] ?>">Abrir</a></td></tr><?php endforeach?><?php if(!$samples):?><tr><td colspan="9" class="empty-state">Nenhuma amostra localizada.</td></tr><?php endif?></tbody></table></div></section>
<?php if($pages>1):?><nav class="correction-pagination" aria-label="Paginação"><?php for($i=1;$i<=$pages;$i++):$query['page']=$i;?><a class="<?= $i===$page?'active':'' ?>" href="?<?= $h(http_build_query($query)) ?>"><?= $i ?></a><?php endfor?></nav><?php endif?>
